void test_gimp_image_roundtrip(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features) {
  GimpImage *image;
  GimpImage *loaded_image;
  gchar *temp_file;
  gboolean success;

  image = create_test_image(gimp, with_unusual_stuff, compat_paths, use_gimp_2_8_features);
  g_assert(image != NULL);

  temp_file = g_strdup_printf("/tmp/gimp_roundtrip_test_XXXXXX.xcf");
  mkstemps(temp_file, 4); // Ensure file is created and we get a unique name

  success = gimp_file_save(GIMP_FILE_SAVE(image), NULL, temp_file, NULL);
  g_assert(success);

  loaded_image = gimp_file_load(temp_file, NULL, NULL);
  g_assert(loaded_image != NULL);

  g_assert(compare_images(image, loaded_image));

  g_object_unref(loaded_image);
  g_object_unref(image);

  g_unlink(temp_file);
  g_free(temp_file);
}
